// CHK-008: Outputs held at zero during reset (GP-10-31, GP-10-03, GP-2-06)
a_CHK_008: assert property (@(posedge clk_i) (!rst_ni) |-> (o_d_valid == 1'b0 && o_alert == 1'b0 && o_alert_integ_fail == 1'b0 && o_intr_gpio == 32'h0 && o_gpio == 32'h0 && o_gpio_en == 32'h0))
  else begin fails_CHK_008++; $display("NNC_FAIL CHK-008 @%0t", $time); end
always_ff @(posedge clk_i) if (!(!rst_ni) && (!rst_ni)) hits_CHK_008 <= hits_CHK_008 + 1;

// CHK-008: same check on the falling clock edge (GP-10-31, GP-10-03, GP-2-06)
a_CHK_008_neg: assert property (@(negedge clk_i) (!rst_ni) |-> (o_d_valid == 1'b0 && o_alert == 1'b0 && o_alert_integ_fail == 1'b0 && o_intr_gpio == 32'h0 && o_gpio == 32'h0 && o_gpio_en == 32'h0))
  else begin fails_CHK_008++; $display("NNC_FAIL CHK-008 @%0t", $time); end
